1:tf1.code:
% Control Lab — 由当前参数生成，可独立运行
clear; clc; close all;
num = [5];
den = [1 5 8 4 0];
sys = tf(num,den);
disp(sys); pole(sys), zero(sys)
Gopen = tf([5],[1 5 8 4 0]);
[GM,PM,Wcg,Wcp] = margin(Gopen);
fprintf("GM=%.6g dB, PM=%.6g deg, wc=%.6g rad/s\n",20*log10(GM),PM,Wcp);
t = linspace(0,5,1501).';
A = 1;
u = A*ones(size(t));
y = lsim(sys,u,t);
figure; plot(t,u,"--",t,y,"LineWidth",1.5); grid on;
xlabel("Time (s)"); ylabel("Amplitude"); legend("Input","Output");
if isstable(sys)
    info = stepinfo(y,t,dcgain(sys)*A,"SettlingTimeThreshold",0.02);
    disp(info);
end
figure; bode(Gopen); grid on;

